#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;

int main() {
    long long y, x;
    cin >> y >> x;

    vector<long long> path;
    path.push_back(x);

    while (x > y) {
        if (x % 10 == 1) {
            x /= 10;
        } else if (x % 2 == 0) {
            x /= 2;
        } else {
            break;
        }
        path.push_back(x);
    }

    if (x != y) {
        cout << "NO\n";
        return 0;
    }

    reverse(path.begin(), path.end());
    cout << "YES\n" << path.size() << '\n';
    for (long long value : path) {
        cout << value << ' ';
    }
    cout << '\n';

    return 0;
}

